CREATE TABLE IF NOT EXISTS "emprestimos" ("id" INTEGER NOT NULL,"tipo" INTEGER NOT NULL,"pessoa" TEXT NULL DEFAULT NULL,"valorTotal" REAL NULL DEFAULT NULL,"numeroParcelas" INTEGER NULL DEFAULT NULL,"dataInicio" DATETIME NOT NULL,"comentario" TEXT NULL DEFAULT NULL,"cancelado" INTEGER NULL DEFAULT 0,"createdDate" DATETIME NOT NULL,"updatedDate" DATETIME NULL DEFAULT NULL,PRIMARY KEY ("id"));
